"""Derivations tied to actual implementation work and retained storage."""
def explain_costs(patterns):
    costs = {
      'Two Sum':('One pass over n values performs a constant number of expected-O(1) dictionary operations per value: n×O(1)=O(n).','At most n previously seen values and indices are stored. The two returned indices are constant-sized.'),
      'Group Anagrams':('Each character is counted once. Each word also initialises/converts 26 counts: O(total characters + 26×number of words).','Signatures require up to 26 counts per group. Group lists retain all input words; account for that output storage separately from character data already in the input.'),
      'Longest Consecutive Sequence':('The set costs O(n) to build. Only sequence starts begin a walk; across all such walks each distinct value is visited once. The nested while therefore totals O(n), not O(n²).','The set holds at most n distinct values; a few integer variables hold each current walk.'),
      'Pair in a Sorted Array':('Each iteration moves left or right, and neither reverses. Their combined movement is at most n positions: O(n).','Only left, right and the current sum are stored; the output has two indices.'),
      '3Sum':('Sorting costs O(n log n). There are O(n) fixed first positions, each with an O(n) pointer scan. O(n²) dominates the sort.','sorted(nums) makes an O(n) copy, and Python sorting can use O(n) temporary storage. Unique triplets require additional output space.'),
      'Container With Most Water':('One pointer moves each iteration, so at most n−1 pairs are examined. Calculating a pair’s area is constant time.','Two indices, one best value and one current area are constant-sized.'),
      'Longest Unique Substring':('right visits each character once; left removes each character at most once. Dictionary updates are expected constant time, so all while iterations combined are O(n).','The frequency dictionary has at most min(n,alphabet size) keys; pointer and answer variables are constant-sized.'),
      'Minimum Size Subarray Sum':('Each positive value enters once and leaves at most once. The nested shrink loop is amortised O(n) across the whole scan.','Only the two boundaries, running sum and best length are kept.'),
      'Max Consecutive Ones III':('Both boundaries move forward at most n times. Updating the zero count is constant time: O(n) total.','Only indices, a zero count and a best length are retained.'),
      'Immutable Range Sum':('Build n prefixes once in O(n). A query does two array lookups and one subtraction: O(1) each, so q queries cost O(q).','The prefix list has n+1 entries; returned answers add O(q) output storage.'),
      'Subarray Sum Equals K':('Scan n values; each prefix lookup and frequency update is expected O(1). Total O(n), even when values are negative.','At most n+1 distinct prefix sums are retained. Store frequencies, not a list of all subarrays.'),
      'Range Addition':('Each of u updates changes two boundaries in O(1), then one n-cell cumulative pass reconstructs the array: O(u+n).','The difference array and output each have O(n) entries.'),
      'Meeting Rooms II':('There are 2n events. Sorting costs O(n log n), followed by one O(n) active-count sweep.','The event list and sorted event copy each contain O(n) items.'),
      'Merge Sorted Arrays':('Every input item is appended exactly once. Two fronts advance across n+m items: O(n+m).','The returned merged list holds n+m items; indices use O(1) auxiliary state.'),
      'Sort Colors':('Each iteration either advances mid or decreases high. Each unknown position is resolved once: O(n).','low, mid and high are the only auxiliary state. Swaps happen in the original array.'),
      'Merge Intervals':('Sorting n intervals costs O(n log n). The merging pass compares each interval only with the last output interval: O(n).','The sorted copy and merged output can each contain n intervals.'),
      'Insert Interval':('Each input interval is processed once by one of the left-copy, merge, or right-copy phases: O(n).','The returned list contains at most n+1 intervals; only indices/endpoints are auxiliary scalars.'),
      'Interval Intersections':('Each comparison advances i or j; neither retreats. At most n+m advances give O(n+m).','Only two indices and current endpoints are auxiliary; intersections occupy output space.'),
      'Lower Bound':('The half-open candidate interval halves after each constant-cost comparison, yielding O(log n) iterations.','Three indices are stored; no sliced subarrays are created.'),
      'Search Rotated Array':('For distinct values, at least one half is sorted and one half can be eliminated each round: O(log n).','Only the inclusive search boundaries and midpoint are retained.'),
      'Koko Eating Bananas':('The speed range contains at most max(piles) candidates, so binary search takes O(log max(piles)) rounds. Each feasibility check scans all n piles: O(n log max(piles)).','The generator used by sum does not create a full list. Only search bounds and a few numeric accumulators are retained.'),
      'Linked List Cycle':('Without a cycle, fast reaches the end. With a cycle, collision occurs after O(n) steps across the reachable chain and cycle.','Both pointers refer to existing nodes; no node set or copied list is stored.'),
      'Middle of Linked List':('slow advances one node per round and fast advances two, so the number of rounds is at most n/2: O(n).','Two node references are constant auxiliary space.'),
      'Happy Number':('Reading all digits for the first reduction costs O(log n) decimal-digit operations. Subsequent values shrink to a small cycle-search state; their total is bounded by the same asymptotic digit cost.','Only a few integer states and digit accumulators are stored; no visited set.'),
      'Reverse Linked List':('The loop processes each of n nodes once and rewrites one next pointer: O(n).','previous, head and following reference existing nodes; no new nodes are allocated.'),
      'Merge Two Sorted Lists':('Each comparison consumes one input node; all n+m nodes are attached once: O(n+m).','Only a dummy node and a tail pointer are allocated. The output reuses the input nodes.'),
      'Remove Nth Node From End':('Advance fast by the requested gap, then move both pointers to the end. Total node advances remain O(list length).','A dummy node plus two pointers occupy constant space. The original nodes are reused.'),
      'Valid Parentheses':('Each of n characters causes at most one push or pop, both amortised O(1): O(n).','In the worst case every character is an unclosed opener, so the stack holds O(n) entries.'),
      'Daily Temperatures':('Each index is pushed once and popped at most once. Although while is nested, its total pops are n: O(n).','The unresolved-index stack and result list can each have n entries.'),
      'Largest Rectangle in Histogram':('Each bar is pushed once and popped once; computing its final area is O(1). The sentinel scan is O(n).','The stack can contain n bars. heights+[0] also creates an O(n) copy, included in the stated O(n) auxiliary bound.'),
      'Sliding Window Maximum':('Each index is appended once, removed from the back at most once, and expires from the front at most once. Total deque operations are O(n).','The deque retains at most k window indices. Output contains n−k+1 maxima.'),
      'First Negative in Each Window':('Each input position is examined once; each negative index enters and leaves the deque once: O(n).','At most k negative indices remain in the current window, plus the returned answers.'),
      'Shortest Subarray With Sum at Least K':('Build n+1 prefix sums. Each prefix index enters and leaves the monotonic deque once: O(n) total.','The prefix array and candidate deque each may contain O(n) entries.'),
      'Merge K Sorted Streams':('There are N output values. Each pop and possible push touches a heap of at most k stream fronts: O(N log k), plus O(k) initial heapification.','The heap retains one front per nonempty stream, O(k); the merged output takes O(N).'),
      'Last Stone Weight':('Heapify is O(n). At most n−1 smash rounds each do a constant number of O(log n) heap operations: O(n log n).','The heap stores up to n weights; scalar smash values are constant-sized.'),
      'Maximum Tree Depth':('Each node is visited once and combines two child results in constant time: O(n).','At most one root-to-leaf chain is active on the recursion stack: O(height), which can be O(n) for a skewed tree.'),
      'Number of Islands':('The outer grid scan is rows×cols. Each land cell is marked before pushing, so it is processed once, with four constant neighbor checks.','The explicit DFS stack may grow to O(rows×cols). The grid is marked in place; no separate visited grid is allocated.'),
      'Validate Binary Search Tree':('Each node checks its bounds once and recursively visits its children: O(n).','The active recursive path uses O(height) stack frames.'),
      'Binary Tree Level Order':('Each node is enqueued and dequeued once, so O(n). Level boundaries do not rescan nodes.','The queue holds O(maximum width) nodes, while returned level lists collectively contain n values.'),
      'Shortest Unweighted Path':('Each reachable vertex enters the queue once, and each outgoing edge is scanned once: O(V+E).','The seen set and queue hold at most V vertices. Input adjacency storage is not copied.'),
      'Rotting Oranges':('Seed the grid in O(rows×cols). Each fresh cell becomes rotten and is queued once; four neighbor checks are constant work.','The multi-source queue can hold O(rows×cols) cells. The input grid itself records visited state.'),
      'Subsets':('There are 2^n subsets. Copying paths into output can cost up to n per subset, so O(n×2^n).','Recursion and the mutable path use O(n). Output holds O(n×2^n) values in the worst case.'),
      'Permutations':('Distinct n items produce n! permutations. Copying a complete path takes O(n): O(n×n!) output work.','Path, used-index set and recursion depth are O(n); the stored permutations add O(n×n!) output.'),
      'Combination Sum':('The search branches over reusable positive candidates until the target is exhausted. The bound is exponential and depends on candidate values and target; sorting adds O(c log c).','Maximum path depth is target/min(candidate). Recursion/path use that bound, with additional storage for every returned combination.'),
      'Jump Game':('Inspect each position once, updating maximum reach in constant time: O(n).','Only an index and furthest reach are kept.'),
      'Non-overlapping Intervals':('Sort n intervals by finish time in O(n log n), then make one O(n) greedy pass.','sorted creates an O(n) copy. End/kept variables use constant storage.'),
      'Gas Station':('Process each of n stations once; restarting a candidate does not restart the scan: O(n).','Only total balance, current tank, start index and current pair are stored.'),
      'Climbing Stairs':('There are n recurrence updates, each combining two prior counts: O(n) arithmetic operations.','Two integer variables replace an n-entry DP array. Large result integers still require their own bit storage.'),
      'Coin Change':('For each amount from 1..A, examine C coin denominations: O(A×C). This is pseudo-polynomial in A, not its bit length.','The DP array stores A+1 counts: O(A). No combination paths are stored.'),
      'Longest Common Subsequence':('Each of n×m character pairs is compared once, with constant recurrence work: O(nm).','Two rows of shorter-string length m+1 are live at once after the swap: O(min(n,m)).'),
      'Course Schedule':('Build edges/indegrees in O(V+E), dequeue each vertex once, and decrement each edge once: O(V+E).','Adjacency lists store E edges, indegrees store V entries, and the queue holds up to V vertices: O(V+E).'),
      'Connected Components':('Initialise V parents. Path compression plus union-by-size makes E operations amortised O(α(V)), giving O((V+E)α(V)).','Parent and size arrays each hold V entries. The input edge list is not copied.'),
      'Dijkstra Shortest Distances':('Each successful relaxation pushes a heap entry. With lazy stale entries, up to O(E+1) entries can be pushed and heap operations cost O(log(V+E)): O((V+E)log(V+E)).','The distance map holds O(V) values; the lazy heap can hold O(E) candidate entries. No decrease-key structure is assumed.'),
      'Implement a Trie':('insert/search/prefix traversal visits each character of its argument once: O(word length) per operation.','Shared prefix nodes are retained; at most one node per inserted character gives O(total inserted characters).'),
      'Find First Occurrence (KMP)':('The prefix table is built in O(m). In search, text advances forward and pattern fallback is amortised across advances: O(n+m).','The pattern-prefix table holds m entries; search uses constant extra indices.'),
      'Word Break With a Trie':('Building the trie costs total dictionary characters. Each of n reachable starts may scan O(n) following characters: O(dictionary characters+n²) worst case.','The trie stores dictionary characters; reachable stores n+1 booleans.'),
      'Single Number':('XOR each of n values once: O(n) under ordinary bounded-integer assumptions.','One accumulator holds the cancellation result.'),
      'Counting Bits':('Fill exactly n entries, each from one smaller entry and one low bit: O(n).','The returned n+1-entry list takes O(n); auxiliary state is constant.'),
      'Greatest Common Divisor':('Euclid’s remainder steps shrink the pair; the number of arithmetic steps is O(log min(|a|,|b|)) for nonzero inputs.','Two running integers plus a remainder are constant in count. Arbitrary-precision operation cost depends on operand bit length.'),
    }
    extra={
      'Contains Duplicate':('Each value causes one expected-O(1) set lookup and at most one insertion: O(n).','The set can retain n distinct values.'),
      'Valid Anagram':('Both Counters inspect all n+m characters once. Comparing counts is bounded by the number of distinct characters.','Frequency maps contain at most alphabet-size distinct keys.'),
      'Valid Palindrome':('Both pointers only move inward. Each character is checked/skipped at most a constant number of times: O(n).','The code never builds a filtered or reversed string; only two indices and temporary characters are retained.'),
      'Trapping Rain Water':('One boundary advances every round, processing each bar once: O(n).','The two boundaries, two maxima and water total are constant-sized.'),
      'Minimum Window Substring':('Count t in O(m). Each s character enters once and exits at most once; Counter updates are constant expected cost: O(n+m).','The Counter may contain keys from s and t, bounded by the alphabet size. Only indices and a best length are additional state; the returned substring is output.'),
      'Longest Repeating Character Replacement':('Both boundaries move at most n times. max(counts.values()) scans at most 26 uppercase keys each time: O(26n)=O(n) for this fixed alphabet.','At most 26 frequency counts and a few scalar boundaries are retained.'),
      'Product of Array Except Self':('One n-element prefix pass and one n-element suffix pass give 2n constant-work iterations: O(n).','The result array is required output. Prefix/suffix accumulators use O(1) auxiliary space.'),
      'Continuous Subarray Sum':('Each of n values updates a remainder and performs expected-O(1) map work: O(n).','At most min(n+1,k) distinct remainders are stored, each with its earliest index.'),
      'K Closest Points to Origin':('A partition scans its active interval once. Random pivot selection yields O(n) expected total scans; adversarial pivot sequences can cause O(n²).','Partitioning swaps existing points and uses constant indices. The returned slice stores k selected points.'),
      'Sort an Array (Merge Sort)':('The recurrence is T(n)=2T(n/2)+O(n): O(log n) levels, each with O(n) merge work, give O(n log n).','Input slices and merge results sum to O(n) peak storage along active recursion; the recursion depth itself is O(log n).'),
      'Meeting Rooms':('Sort n intervals in O(n log n), then check n−1 neighbors in O(n).','The sorted interval copy requires O(n) storage.'),
      'Minimum Arrows to Burst Balloons':('Sort by end in O(n log n); scan each interval once in O(n).','Sorting creates O(n) interval references. Position and arrow count are constant-sized.'),
      'Find Minimum in Rotated Sorted Array':('Each comparison removes roughly half the candidate indices: O(log n) for distinct values.','Only left/right/mid are used.'),
      'First and Last Position of Element':('Two independent O(log n) boundary searches give O(log n), not O(n).','Each search keeps constant indices; no slices or index lists are made.'),
      'Linked List Cycle Entrance':('The collision phase and entrance phase each take O(n) node steps; adding two linear passes remains O(n).','Three pointers reference existing nodes, with no history set.'),
      'Find the Duplicate Number':('Floyd’s two phases each follow O(n) successors in the implicit index graph.','Only slow/fast/seeker indices are stored; the input is not modified.'),
      'Reorder List':('Find midpoint, reverse half, then interleave. These three linear passes total O(n).','All links are rewired in place with a constant number of saved node references.'),
      'Add Two Numbers':('Each loop consumes at most one digit from each list: O(max(n,m)), plus one possible carry digit.','New output nodes total O(max(n,m)); only a carry and pointers are auxiliary.'),
      'Min Stack':('Each operation reads or modifies the end of one list; append/pop are amortised O(1), and top/min are O(1).','Store one (value,minimum) pair per stack entry: O(n).'),
      'Evaluate Reverse Polish Notation':('Each token is read once and pushed/popped at most once: O(n) arithmetic operations.','The operand stack can grow to O(n) entries.'),
      'Moving Average From a Stream':('Each next call adds one value and removes at most one old value from a deque: O(1).','Only the last size values and a running sum are retained: O(size).'),
      'Longest Subarray Within Absolute Limit':('Each index enters/exits both deques at most once; left/right only advance: O(n) total.','Each deque can retain O(n) indices in the worst case; a particular current window may be smaller.'),
      'Kth Largest Element':('Three-way partition scans an active interval. Random pivots give O(n) expected total work; the worst sequence gives O(n²).','All partitioning occurs inside nums. Only scalar boundaries and a pivot are additional storage.'),
      'Top K Frequent Elements':('Counting is O(n), placing u unique values is O(u), and scanning n frequency buckets is O(n): O(n) total because u≤n.','Counter holds u entries and buckets have n+1 lists plus u values. Peak auxiliary space is O(n).'),
      'Task Scheduler':('Count every task once, then scan the distinct labels a constant number of times: O(task count).','The Counter holds one entry per label. The final scheduling formula needs only scalars.'),
      'Invert Binary Tree':('Visit each node once, swap two pointers and recurse: O(n).','The tree is mutated in place; only O(height) recursion frames are added.'),
      'Lowest Common Ancestor':('In the worst case both subtrees are searched and each node is visited once: O(n).','Only the active recursive path and two child results per call are retained: O(height).'),
      'Word Ladder':('For each visited word, try 26 letters at each of L positions. Each candidate string construction/hash costs O(L), giving O(26×L²×word count).','The remaining-word set and queue retain O(word count×L) character storage in the worst case.'),
      '01 Matrix':('Seed every zero and process each cell at most once with four neighbor checks: O(rows×cols).','Distance output stores rows×cols integers; the queue may also contain O(rows×cols) positions.'),
      'Word Search':('Every grid cell can start a search branching into up to four neighbors for L characters. O(rows×cols×4^L) is a safe upper bound; path reuse checks prune many branches.','The recursion depth and path-specific used set are O(L); the board is not copied.'),
      'Generate Parentheses':('There are Catalan(n) valid outputs. Building each 2n-character string yields O(n×Catalan(n)); invalid prefixes are pruned.','Path and recursion depth are O(n); output stores O(n×Catalan(n)) characters.'),
      'Best Time to Buy and Sell Stock':('Each price updates cheapest and best once: O(n).','Two running values are stored, without any price slices.'),
      'Maximum Subarray (Kadane)':('Every array index is visited once, with two constant-work maxima: O(n).','The implementation uses an index loop and two sums, avoiding the O(n) nums[1:] copy.'),
      'House Robber':('Exactly one recurrence update is performed per house: O(n).','Only the two previous prefix optima and current value are retained, giving O(1).'),
      'Longest Increasing Subsequence':('For each of n values, bisect_left searches at most n sorted tails in O(log n). Append or replacement is amortised O(1): O(n log n).','tails can grow to n entries. Only length is returned; reconstruction would require additional predecessor storage.'),
      'Unique Paths':('The multiplicative binomial loop runs min(m−1,n−1) times. This is O(min(m,n)) arithmetic operations, with nonconstant big-integer bit cost for large counts.','Only a fixed number of integer variables are retained. Their bit size grows with the count, so O(1) means number of auxiliary integer variables, not constant total bits.'),
      'Edit Distance':('Every pair of prefix lengths is evaluated once: n×m constant recurrence steps, yielding O(nm).','The only DP row has min(n,m)+1 entries. Saved above/diagonal values are scalar, so O(min(n,m)).'),
      'Clone Graph':('Every reachable vertex is queued once and each adjacency edge is appended once: O(V+E).','Independent copied adjacency lists retain O(V+E) output. The queue is O(V); no original adjacency list is reused.'),
      'Redundant Connection':('n union/find operations with path compression and union-by-size take amortised O(nα(n)).','Two n+1-entry arrays store parents and component sizes.'),
      'Replace Words':('Insert each dictionary character once, then walk each sentence word at most its length: O(dictionary characters+sentence characters).','The trie stores dictionary prefixes; the replaced sentence occupies output storage.'),
      'Longest Common Prefix':('Each visited character position is compared across the words until a mismatch. Relevant characters are inspected at most once, bounded by their total input length.','Only loop indices and a reference to the first word are auxiliary. One final returned prefix slice costs O(prefix length) output storage.'),
      'Reverse Bits':('Exactly 32 constant-width bit steps are performed, regardless of the input’s numeric value: O(32)=O(1).','Only n, result and a loop counter are retained.'),
      'Pow(x, n)':('Integer exponent n is halved every iteration, so there are O(log |n|) multiplications; n=0 returns immediately.','Only base, exponent and result are retained. Floating-point values occupy fixed storage.'),
      'Rotate Image':('Transpose visits about n²/2 off-diagonal pairs, then reversing n rows visits n² elements: O(n²).','Swaps and row.reverse operate in place; only indices are auxiliary.'),
      'Spiral Matrix':('Every cell is appended exactly once as layer boundaries shrink: O(rows×cols).','Four boundary variables are auxiliary; the returned traversal stores every matrix value.'),
      'Set Matrix Zeroes':('Inspect/mark each cell and then apply markers. First-row/column passes add O(rows+cols), leaving O(rows×cols).','The matrix’s own first row/column hold markers. Only two booleans and loop indices are additional storage.'),
      'Search a 2D Matrix':('The candidate interval contains rows×cols virtual positions and halves each round: O(log(rows×cols)).','The matrix is never flattened or copied; quotient/remainder recover coordinates using constant state.'),
      'Game of Life':('Each cell checks eight neighbors, a fixed constant, followed by one commit pass: O(rows×cols).','Two generations are encoded in each existing cell’s bits; no second matrix is allocated.'),
    }
    costs.update(extra)
    for p in patterns:
        for e in p['examples']:
            assert e['title'] in costs,e['title']
            e['timeReason'],e['spaceReason']=costs[e['title']]
            e.setdefault('optimality','This is a standard efficient approach under the stated contract. Output storage and Python allocation costs are included explicitly above; specialised input bounds may permit different tradeoffs.')
    for p in patterns:
        for e in p['examples']:
            if e['title'] in ['K Closest Points to Origin','Kth Largest Element']:
                e['patternNote']='Selection connection: the primary code uses quickselect for expected-linear selection. A heap is the predictable-time, input-preserving alternative. Compare the tradeoff rather than assuming every selection task needs a heap.'
            if e['title']=='Unique Paths':e['patternNote']='DP connection: the cell recurrence explains the count. Because this version has no obstacles, the primary code uses a faster combinatorial count. Use DP when cells carry obstacles or additional state.'
            if e['title']=='Task Scheduler':e['patternNote']='Scheduling connection: a heap can simulate this process, but counting gives the minimum length directly when only the length is required.'
